architecture.h4_f:
msg = CBOR{v:1, ຂໍ້ຄວາມ, ຕອບກັບ, ສົ່ງ_at}
ct = AES-GCM-256-ເຂົ້າລະຫັດ(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, reply_to?, thread_id?, mentions?, send_at}
ct = AES-GCM-256-ເຂົ້າລະຫັດ(room_key, nonce, pt, aad=hex(room_id))
ສາຍ = CBOR{
  v: 1,
  ciphertext: hex(ct), // ຄວາມຍາວຕົວແປ
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  send_at: unix_ms
}

cryptoWire.h5_f:
ພາຍນອກ = CBOR{
  source_node: hex32,
  target_user: int64,
  inner_ciphertext: bytes,
  inner_nonce: bytes,
  send_at: unix_ms
}
sig = Ed25519-Sign(source_priv, ນອກ)
POST /federation/deliver { envelope: ນອກ, sig: hex64 }

auth.h1_f:
POST /api/authentication/ລົງທະບຽນ
  { ຊື່ຜູ້ໃຊ້, ລະຫັດຜ່ານ, x25519_public_key, display_name, ໂທລະສັບ?, ອີເມວ?, avatar_emoji }

ຕອບກັບ 201 ສ້າງ:
  { access_token, refresh_token, user_id, ຊື່ຜູ້ໃຊ້, ... }

auth.h3_f:
access_token payload:
  { sub: user_id, jti: device_id, ພິມ: "access", exp: now + 15min }
refresh_token payload:
  { sub: user_id, jti: device_id, ພິມ: "refresh", exp: now + 30d }

HS256-ເຊັນຊື່ດ້ວຍຄວາມລັບ 64-byte ຂອງ node ຈາກ .env

auth.h4_f:
register_begin(): challenge = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, challenge }
                    ທາງເລືອກກັບຄືນ

register_finish(ການ​ຢັ້ງ​ຢືນ​)​:
  ຢືນຢັນການຢັ້ງຢືນຕໍ່ກັບTPM / Secure Enclave root CA
  ເກັບຮັກສາ { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/ຢັ້ງຢືນ { nonce }
  →ອຸປະກອນໃຫມ່ລົງທະບຽນ; JWTs ກັບຄືນມາ.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-ເຂົ້າລະຫັດ(room_key, nonce, CBOR_payload, aad=room_id)

ກອບພັດລົມ: { ປະເພດ: "m", ຫ້ອງ, ຂໍ້ຄວາມ: {id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
ສະຫຼຸບ POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL ສຸດຍັງບໍ່ແລ້ວ: 24 ຊົ່ວໂມງ

files.h4_f:
deny_list = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
ຖ້າ magic.from_buffer(buf[:1024]) ໃນ deny_list: return 415

presence.h1_f:
ລູກຄ້າ: ໃນການກົດແປ້ນພິມທຳອິດ → ສົ່ງ {type:"t", state:"start"}
         ບໍ່ມີການສົ່ງຕໍ່ອີກ 3 ວິນາທີ ເວັ້ນເສຍແຕ່ວ່າສະຖານະມີການປ່ຽນແປງ
         10 ວິນາທີຫຼັງຈາກການກົດແປ້ນພິມຄັ້ງສຸດທ້າຍ → ສົ່ງ {type:"t", state:"stop"}
ຜູ້ຮັບ: auto-stop 10 s ຫຼັງຈາກ "ເລີ່ມຕົ້ນ" ສຸດທ້າຍຖ້າບໍ່ມີ "ຢຸດ" ມາຮອດ

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS ອອກອາກາດ {type:"c", kind:"invite", call_id}
WS ອອກອາກາດ {type:"c", kind:"offer", sdp}
WS ອອກອາກາດ {type:"c", type:"answer", sdp}
WS ອອກອາກາດ {type:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
ຊອງຈົດໝາຍ = {
  source_node : hex32,
  target_user : int64,
  inner_ciphertext: bytes,
  inner_nonce : ໄບຕ໌,
  send_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(ຊອງຈົດໝາຍ))
POST /federation/deliver { envelope, sig }

gossip.h3_f:
advertisement = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(ໂຄສະນາ))
gossip payload: [..., {ໂຄສະນາ, sig}, ...]

ຜູ້ຮັບ: ຢືນຢັນ sig ຕໍ່ກັບ ad.pubkey → store iff ok
ເພີ່ມເຕີມ: PoW ຂອງ 2^18 ອັນດັບສູນຢູ່ {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template ກັບ {
  random = ການສຸ່ມຂອງພວກເຮົາ,
  server_name = ຊື່ເຈົ້າພາບຂອງພວກເຮົາ (ຫຼື ECH-wrapped),
  session_id = id session ຂອງພວກເຮົາ,
}
JA4 = t13d_xxxx_xxxx_xxxx (ກົງກັບ Chrome ຄົງທີ່ໃນປັດຈຸບັນ)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {ຊື່: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domain(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
ເວັບ SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
tool = sign_tool
input = ແຫຼ່ງຕົ້ນໄມ້, keys/release.key
manifest = {
  ຮຸ່ນ: "0.1.0",
  built_at: unix_ms,
  ໄຟລ໌: [{ເສັ້ນທາງ, sha256, ຂະຫນາດ}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
output = INTEGRITY.sig.json = {manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
ສ້າງ: POST /api/bots {ຊື່ຜູ້ໃຊ້, ຊື່ສະແດງ, ລະຫັດ}
          → {bot_id, token, pubkey}
ແລ່ນ: ໃນຂະບວນການ (coroutine ພາຍໃນ node)
      OR ພາຍນອກ (ແບບສຳຫຼວດຍາວ /api/bots/{id}/ອັບເດດ, token-auth'd)
ຂໍ້ຄວາມ: {ຂໍ້ຄວາມ, ລາຍເຊັນ: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
ສຸດ /start {
  ປ່ອຍສຽງ "ຍິນດີຕ້ອນຮັບ, {ctx.first_name}"
}
ສຸດ /add <item> {
  state.list = (state.list ຫຼື []) + [ctx.args.item]
  ປ່ອຍ "ເພີ່ມ: {ctx.args.item}"
}

security.h4_f:
canary.txt (ປະຈໍາວັນ):
  {date, sig: Ed25519-Sign(release_priv, date)}
ລູກຄ້າກວດສອບ → ຂາດ ຫຼືບໍ່ຖືກຕ້ອງ ⇒ ສົງໃສວ່າມີການປະນີປະນອມ

ສຸກເສີນ:
  admin POST /api/admin/revoke-all {reason}
  node broadcasts {type:"n", event:"compromise", ເຫດຜົນ}
  ລູກຄ້າເຊັດກະແຈ, ບັງຄັບ bootstrap ຄືນໃໝ່

debugging.h2_f:
ອັດຕາ histograms (ຕໍ່ເສັ້ນທາງ + ວິທີການ):
  vortex_http_requests_total{ເສັ້ນທາງ,ວິທີການ,ສະຖານະ}
  vortex_http_request_duration_seconds_bucket{ເສັ້ນທາງ,ວິທີການ,le}

websocket gauges:
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{room,user}

ເຄົາເຕີແບບກຳນົດເອງ:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

